def parse_duration_words(s):
    tokens = s.split(" ")
    total = 0
    i = 0
    while i < len(tokens):
        num = int(tokens[i])
        unit = tokens[i + 1]
        if unit.startswith("hour"):
            total += num * 60
        elif unit.startswith("minute"):
            total += num
        i += 2
    return total

def countdown_to_multiple_targets(current_hhmm, targets_list):
    ch, cm = map(int, current_hhmm.split(":"))
    cur = ch * 60 + cm
    best = None
    for t in targets_list:
        th, tm = map(int, t.split(":"))
        tar = th * 60 + tm
        diff = tar - cur
        if diff < 0:
            diff += 1440
        if best is None or diff < best:
            best = diff
    return best

def overlaps_midnight(start_hhmm, end_hhmm):
    sh, sm = map(int, start_hhmm.split(":"))
    eh, em = map(int, end_hhmm.split(":"))
    return (eh * 60 + em) < (sh * 60 + sm)

def add_months_to_date(y, m, d, n_months):
    def is_leap(yr):
        return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)
    total = (y * 12 + (m - 1)) + n_months
    ny = total // 12
    nm = total % 12 + 1
    dim = [31, 29 if is_leap(ny) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][nm - 1]
    nd = min(d, dim)
    return (ny, nm, nd)

def subtract_months_from_date(y, m, d, n_months):
    def is_leap(yr):
        return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)
    total = (y * 12 + (m - 1)) - n_months
    ny = total // 12
    nm = total % 12 + 1
    dim = [31, 29 if is_leap(ny) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][nm - 1]
    nd = min(d, dim)
    return (ny, nm, nd)
